Effect.catch(program, () => Effect.void)
Effect.catch(program, () => Effect.unit)
Effect.catch(program, () => { return Effect.void })
Effect.catch(program, function () { return Effect.unit })
Effect.catchTag('Timeout', () => Effect.void)
Effect.catchReason('Corrupted', (error) => Effect.unit)
Effect.catchTags({ Timeout: () => Effect.void, Corrupted: () => Effect.unit })
Effect.catchReasons({ Corrupted: () => Effect.void })
Effect.catchTags({ Timeout() { return Effect.void } })
pipe(program, Effect.catch(() => Effect.void))
